-- =====================================================================
-- table_import.sql - Diabetes cohort capstone (synthetic data)
-- Creates the 9 tables and loads the raw data, errors included:
-- cleaning is part of the exercise, so nothing has been corrected here.
--
-- In DBeaver: create an empty database named "Diabetes_capstone", 
-- open an SQL editor on it, and copy paste the content of this file.
-- Then Execute SQL Script (Alt+X), not Execute statement (Ctrl+Enter).
-- Expected row counts are checked at the end of the script.
-- =====================================================================

-- Drop in reverse dependency order so the script can be run again

DROP TABLE IF EXISTS family_history;
DROP TABLE IF EXISTS treatments;
DROP TABLE IF EXISTS consultations;
DROP TABLE IF EXISTS glucose_history;
DROP TABLE IF EXISTS gene_expression;
DROP TABLE IF EXISTS lifestyle;
DROP TABLE IF EXISTS patient_centre;
DROP TABLE IF EXISTS patients;
DROP TABLE IF EXISTS care_centres;

-- ---------------------------------------------------------------------
-- care_centres  (source: Centres_soins.csv)
-- ---------------------------------------------------------------------
CREATE TABLE care_centres (
    centre_id                TEXT PRIMARY KEY,
    centre_name              TEXT,
    region                   TEXT,
    centre_type              TEXT
);

-- ---------------------------------------------------------------------
-- patients  (source: Patients.csv)
-- ---------------------------------------------------------------------
CREATE TABLE patients (
    patient_id               TEXT PRIMARY KEY,
    age                      INTEGER,
    sex                      TEXT,
    weight_kg                DOUBLE PRECISION,
    height_cm                DOUBLE PRECISION,
    blood_group              TEXT,
    glucose_mg_dl            DOUBLE PRECISION,
    insulin_uiu_ml           DOUBLE PRECISION,
    corticosteroids          TEXT
);

-- ---------------------------------------------------------------------
-- patient_centre  (source: Patients_centres.csv)
-- ---------------------------------------------------------------------
CREATE TABLE patient_centre (
    patient_id               TEXT PRIMARY KEY,
    centre_id                TEXT NOT NULL,
    FOREIGN KEY (patient_id) REFERENCES patients (patient_id),
    FOREIGN KEY (centre_id) REFERENCES care_centres (centre_id)
);

-- ---------------------------------------------------------------------
-- lifestyle  (source: Hygiene_vie.csv)
-- ---------------------------------------------------------------------
CREATE TABLE lifestyle (
    patient_id               TEXT PRIMARY KEY,
    stress_score             INTEGER,
    stress_level             TEXT,
    sleep_h                  DOUBLE PRECISION,
    activity_min_week        DOUBLE PRECISION,
    activity_level           TEXT,
    fruit_veg_per_day        DOUBLE PRECISION,
    sugary_drinks_per_week   INTEGER,
    fast_food_per_week       DOUBLE PRECISION,
    diet_score               DOUBLE PRECISION,
    diet_quality             TEXT,
    smoker                   TEXT,
    alcohol_units_week       DOUBLE PRECISION,
    FOREIGN KEY (patient_id) REFERENCES patients (patient_id)
);

-- ---------------------------------------------------------------------
-- gene_expression  (source: Expression_genique.csv)
-- ---------------------------------------------------------------------
CREATE TABLE gene_expression (
    patient_id               TEXT PRIMARY KEY,
    TCF7L2                   DOUBLE PRECISION,
    PPARG                    DOUBLE PRECISION,
    KCNJ11                   DOUBLE PRECISION,
    ABCC8                    DOUBLE PRECISION,
    SLC30A8                  DOUBLE PRECISION,
    CDKAL1                   DOUBLE PRECISION,
    CDKN2A                   DOUBLE PRECISION,
    IGF2BP2                  DOUBLE PRECISION,
    HHEX                     DOUBLE PRECISION,
    FTO                      DOUBLE PRECISION,
    IRS1                     DOUBLE PRECISION,
    GCK                      DOUBLE PRECISION,
    GCKR                     DOUBLE PRECISION,
    MTNR1B                   DOUBLE PRECISION,
    KCNQ1                    DOUBLE PRECISION,
    ADCY5                    DOUBLE PRECISION,
    GLIS3                    DOUBLE PRECISION,
    JAZF1                    DOUBLE PRECISION,
    HNF1A                    DOUBLE PRECISION,
    FOREIGN KEY (patient_id) REFERENCES patients (patient_id)
);

-- ---------------------------------------------------------------------
-- glucose_history  (source: Historique_glycemique.csv)
-- ---------------------------------------------------------------------
CREATE TABLE glucose_history (
    patient_id               TEXT NOT NULL,
    measure_date             DATE,
    glucose_mg_dl            DOUBLE PRECISION,
    weight_kg                DOUBLE PRECISION,
    blood_pressure           TEXT,
    hba1c_pct                DOUBLE PRECISION,
    FOREIGN KEY (patient_id) REFERENCES patients (patient_id)
);

-- ---------------------------------------------------------------------
-- consultations  (source: Consultations.csv)
-- ---------------------------------------------------------------------
CREATE TABLE consultations (
    patient_id               TEXT NOT NULL,
    consult_date             DATE,
    consult_type             TEXT,
    provider                 TEXT,
    reason                   TEXT,
    FOREIGN KEY (patient_id) REFERENCES patients (patient_id)
);

-- ---------------------------------------------------------------------
-- treatments  (source: Traitements.csv)
-- ---------------------------------------------------------------------
CREATE TABLE treatments (
    patient_id               TEXT NOT NULL,
    drug_name                TEXT,
    start_date               DATE,
    end_date                 DATE,
    dosage                   TEXT,
    drug_class               TEXT,
    FOREIGN KEY (patient_id) REFERENCES patients (patient_id)
);

-- ---------------------------------------------------------------------
-- family_history  (source: Antecedents_familiaux.csv)
-- ---------------------------------------------------------------------
CREATE TABLE family_history (
    patient_id               TEXT NOT NULL,
    relative                 TEXT,
    condition                TEXT,
    FOREIGN KEY (patient_id) REFERENCES patients (patient_id)
);

-- care_centres: 24 rows
BEGIN TRANSACTION;
COMMIT;

-- patients: 1500 rows
BEGIN TRANSACTION;
COMMIT;

-- patient_centre: 1500 rows
BEGIN TRANSACTION;
COMMIT;

-- lifestyle: 1500 rows
BEGIN TRANSACTION;
COMMIT;

-- gene_expression: 1500 rows
BEGIN TRANSACTION;
COMMIT;

-- glucose_history: 11565 rows
BEGIN TRANSACTION;
COMMIT;

-- consultations: 3609 rows
BEGIN TRANSACTION;
COMMIT;

-- treatments: 2432 rows
BEGIN TRANSACTION;
COMMIT;

-- family_history: 1662 rows
BEGIN TRANSACTION;
COMMIT;

-- ---------------------------------------------------------------------
-- Check: every n_rows must equal expected_rows
-- ---------------------------------------------------------------------
SELECT 'care_centres' AS table_name, COUNT(*) AS n_rows, 24 AS expected_rows FROM care_centres
UNION ALL
SELECT 'patients' AS table_name, COUNT(*) AS n_rows, 1500 AS expected_rows FROM patients
UNION ALL
SELECT 'patient_centre' AS table_name, COUNT(*) AS n_rows, 1500 AS expected_rows FROM patient_centre
UNION ALL
SELECT 'lifestyle' AS table_name, COUNT(*) AS n_rows, 1500 AS expected_rows FROM lifestyle
UNION ALL
SELECT 'gene_expression' AS table_name, COUNT(*) AS n_rows, 1500 AS expected_rows FROM gene_expression
UNION ALL
SELECT 'glucose_history' AS table_name, COUNT(*) AS n_rows, 11565 AS expected_rows FROM glucose_history
UNION ALL
SELECT 'consultations' AS table_name, COUNT(*) AS n_rows, 3609 AS expected_rows FROM consultations
UNION ALL
SELECT 'treatments' AS table_name, COUNT(*) AS n_rows, 2432 AS expected_rows FROM treatments
UNION ALL
SELECT 'family_history' AS table_name, COUNT(*) AS n_rows, 1662 AS expected_rows FROM family_history;
